[DataContractAttribute]
public class RMarketJson_Binance_ExchangeInfo
{
    private str timezone;
    private int64 serverTime;
    private List rateLimits;
    private List exchangeFilters;
    private List symbols;

}

Method.Source:
/// <summary> Получает или устанавливает часовой пояс сервера </summary>
/// <param name="_timezone"> Часовой пояс сервера UTC </param>
/// <returns> Часовой пояс сервера UTC </returns>
[DataMember('timezone')]
public str parmTimezone(str _timezone = timezone)
{
    timezone = _timezone;
    return timezone;
}

/// <summary> Получает или устанавливает время сервера </summary>
/// <param name="_serverTime"> Время сервера в миллисекундах </param>
/// <returns> Время сервера в миллисекундах </returns>
[DataMember('serverTime')]
public int64 parmServerTime(int64 _serverTime = serverTime)
{
    serverTime = _serverTime;
    return serverTime;
}

/// <summary> Получает или устанавливает лимиты запросов </summary>
/// <param name="_rateLimits"> Список ограничений скорости </param>
/// <returns> Список ограничений скорости </returns>
[DataMember('rateLimits'), DataCollectionAttribute(Types::Class, classStr(RMarketJson_Binance_ExchangeInfo_RateLimit))]
public List parmRateLimits(List _rateLimits = rateLimits)
{
    rateLimits = _rateLimits;
    return rateLimits;
}

/// <summary> Получает или устанавливает фильтры биржи </summary>
/// <param name="_exchangeFilters"> Фильтры уровня биржи </param>
/// <returns> Фильтры уровня биржи </returns>
[DataMember('exchangeFilters'), DataCollectionAttribute(Types::Class, classStr(RMarketJson_Binance_ExchangeInfo_Filter))]
public List parmExchangeFilters(List _exchangeFilters = exchangeFilters)
{
    exchangeFilters = _exchangeFilters;
    return exchangeFilters;
}

/// <summary> Получает или устанавливает информацию о символах </summary>
/// <param name="_symbols"> Список торговых инструментов </param>
/// <returns> Список торговых инструментов </returns>
[DataMember('symbols'), DataCollectionAttribute(Types::Class, classStr(RMarketJson_Binance_ExchangeInfo_Symbol))]
public List parmSymbols(List _symbols = symbols)
{
    symbols = _symbols;
    return symbols;
}
